resource "aws_kms_key" "data" {
  description = "customer data at rest"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowUse"
        Effect    = "Allow"
        Principal = { AWS = "*" }          # any principal in the account
        Action    = ["kms:Decrypt", "kms:GenerateDataKey", "kms:PutKeyPolicy"]
        Resource  = "*"
        # no Condition block
      }
    ]
  })
}

# ingestion service role -- only writes, never reads back
resource "aws_iam_role_policy" "ingestion" {
  policy = jsonencode({
    Statement = [{
      Effect   = "Allow"
      Action   = ["kms:Decrypt", "kms:GenerateDataKey"]
      Resource = aws_kms_key.data.arn
    }]
  })
}
